<script setup lang="ts">
import {useWorkModeText} from '../workMode'
const {w}=useWorkModeText()
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {usePhaseThreeText} from '../phaseThreeText'
import {dateRangeValid} from '../timekeepingUi'
import {addDays,storeToday,hours,localInput} from '../time'
import {batchEligible,reviewBoardText,reviewBoardError} from '../approvalWorkbench'
import type {ReviewBoard,ReviewCategory,ReviewPreview,ReviewCandidate,ReviewOutcome} from '../approvalWorkbench'
import {WorkforceApiError} from '../api'
import PhaseStatus from '../components/PhaseStatus.vue'
import ApprovalDetail from './ApprovalDetail.vue'
import ApprovalBatchPreview from '../components/ApprovalBatchPreview.vue'
const personFilter=ref<string|null>(null),priorSearch=ref(''),priorCategory=ref<ReviewCategory>('exception')
const route=useRoute(),{api,home,t,p,base,store,current,loading,busy,failure,load,english}=usePhasePage(),{q,issue}=usePhaseThreeText(),b=(key:Parameters<typeof reviewBoardText>[0])=>reviewBoardText(key,english())
const from=ref(typeof route.query.from==='string'?route.query.from:addDays(storeToday(),-1)),to=ref(typeof route.query.to==='string'?route.query.to:from.value),category=ref<ReviewCategory>(['all','normal','manager','exception','waiting','stale','current','exempt'].includes(String(route.query.category))?route.query.category as ReviewCategory:'exception'),positionId=ref(''),search=ref(String(route.query.search||'')),offset=ref(0),data=ref<ReviewBoard|null>(null),expanded=ref(''),all=ref(false),ids=ref<string[]>([]),excluded=ref<string[]>([]),preview=ref<ReviewPreview|null>(null),outcomes=ref<ReviewOutcome[]>([]),lastCandidates=ref<ReviewCandidate[]>([]),batchFailure=ref('')
const filter=computed(()=>({from:from.value,to:to.value,employeeId:personFilter.value,category:category.value,positionId:positionId.value||null,search:search.value.trim()})),key=computed(()=>JSON.stringify(filter.value)),loadedKey=ref(''),fresh=computed(()=>loadedKey.value===key.value),attempt=ref<{items:ReviewCandidate[];note:string;offset:number}|null>(null)
const selectedCount=computed(()=>all.value?Math.max(0,(data.value?.eligible||0)-excluded.value.length):ids.value.length),pageEligible=computed(()=>data.value?.items.filter(batchEligible)||[]),pageChecked=computed(()=>pageEligible.value.length>0&&pageEligible.value.every(e=>selected(e.row.schedule.id)))
watch([from,to,category,positionId,search,personFilter],()=>{offset.value=0;clearSelection()})
function clearSelection(){if(attempt.value)return;all.value=false;ids.value=[];excluded.value=[];preview.value=null}
function selected(id:string){return all.value?!excluded.value.includes(id):ids.value.includes(id)}
function toggle(id:string,on:boolean){if(busy.value||attempt.value||!fresh.value)return;preview.value=null;if(all.value)excluded.value=on?excluded.value.filter(v=>v!==id):[...new Set([...excluded.value,id])];else ids.value=on?[...new Set([...ids.value,id])]:ids.value.filter(v=>v!==id)}
function pageSelect(on:boolean){pageEligible.value.forEach(e=>toggle(e.row.schedule.id,on))}
function refresh(){if(attempt.value||busy.value)return;if(!dateRangeValid(from.value,to.value)){failure.value=p('invalid');return}const captured=key.value;const params=new URLSearchParams({from:from.value,to:to.value,category:category.value,search:search.value.trim(),limit:'50',offset:String(offset.value),...(positionId.value?{positionId:positionId.value}:{}),...(personFilter.value?{employeeId:personFilter.value}:{})});void load(()=>api().get<ReviewBoard>('/approval-board?'+params),v=>{if(captured!==key.value)return;data.value=v;loadedKey.value=captured})}
function openPerson(employeeId:string){priorSearch.value=search.value;priorCategory.value=category.value;personFilter.value=employeeId;category.value='all';offset.value=0;clearSelection();refresh()}
function backToPeople(){search.value=priorSearch.value;personFilter.value=null;category.value=priorCategory.value;offset.value=0;clearSelection();refresh()}
function move(delta:number){offset.value=Math.max(0,offset.value+delta);refresh()}
function selectAll(){if(!fresh.value)return;all.value=true;ids.value=[];excluded.value=[];preview.value=null}
function previewBatch(){if(!fresh.value||!selectedCount.value||attempt.value)return;batchFailure.value='';const captured=key.value;void load(()=>api().put<ReviewPreview>('/approval-board/preview',{filter:filter.value,all:all.value,ids:ids.value,excluded:excluded.value}),v=>{if(captured!==key.value||!fresh.value)return;preview.value=v;outcomes.value=[];lastCandidates.value=v.items})}
function start(note:string){if(busy.value||attempt.value||!preview.value)return;attempt.value={items:preview.value.items.map(item=>({...item})),note,offset:0};void send()}
async function send(){
 if(busy.value||!attempt.value)return;busy.value=true;batchFailure.value='';const saved=attempt.value,client=api(),shop=store.value
 try{while(saved.offset<saved.items.length){const block=saved.items.slice(saved.offset,saved.offset+100);const result=await client.put<{items:ReviewOutcome[]}>('/approval-board/commit',{note:saved.note,items:block});if(!current()||store.value!==shop)return;outcomes.value.push(...result.items);saved.offset+=block.length}attempt.value=null;preview.value=null;all.value=false;ids.value=[];excluded.value=[]}
 catch(e){if(!current()||store.value!==shop)return;batchFailure.value=e instanceof WorkforceApiError?reviewBoardError(e.code,english()):b('retryHint');if(e instanceof WorkforceApiError&&e.status<500){attempt.value=null}}
 finally{if(current()&&store.value===shop){busy.value=false;if(!attempt.value)refresh()}}
}
function saved(){clearSelection();refresh()}
function stamp(v:string|null){return v&&data.value?localInput(v,data.value.timezone).replace('T',' '):'—'}
function person(id:string){const item=lastCandidates.value.find(c=>c.scheduleId===id);return item?item.date+' '+item.employeeName+' '+item.employeeNo:id}
onMounted(()=>{if(typeof route.query.employeeId==='string')personFilter.value=route.query.employeeId;refresh()})
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{b('title')}}</h2><RouterLink v-if="home?.employeeManage" :to="base+'/work-summary'">{{q('summary')}}</RouterLink></header><form class="wf-filters" @submit.prevent="refresh"><label>{{p('from')}}<input v-model="from" type="date" required :disabled="busy||!!attempt"></label><label>{{p('to')}}<input v-model="to" type="date" :min="from" :max="addDays(from,30)" required :disabled="busy||!!attempt"></label><label>{{b('position')}}<select v-model="positionId" :disabled="busy||!!attempt"><option value="">{{b('allPositions')}}</option><option v-for="pos in data?.positions||[]" :key="pos.id" :value="pos.id">{{pos.name}}</option></select></label><label>{{b('search')}}<input v-model="search" type="search" maxlength="100" :disabled="busy||!!attempt"></label><button :disabled="loading||busy||!!attempt">{{b('query')}}</button><button type="button" :disabled="busy||!!attempt" @click="from=addDays(storeToday(),-1);to=from;refresh()">{{b('yesterday')}}</button></form><nav class="wf-subnav wf-review-tabs"><button v-for="c in (['all','normal','manager','exception','waiting','stale','current','exempt'] as ReviewCategory[])" :key="c" :class="{primary:category===c}" :disabled="busy||!!attempt" @click="category=c;offset=0;refresh()">{{b(c)}} {{data?.counts[c]||0}}</button></nav><PhaseStatus :failure="failure" :loading="loading"/><p v-if="!fresh&&data" class="wf-hint">{{b('changedFilter')}}</p><p class="wf-hint">{{b('managerHint')}} {{b('normalHint')}}</p><div v-if="home?.employeeManage" class="wf-form-actions"><span>{{b('eligible')}} {{data?.eligible||0}} · {{b('selected')}} {{selectedCount}}</span><button :disabled="!fresh||loading||busy||!!attempt||!data?.eligible" @click="selectAll">{{b('selectAll')}}</button><button :disabled="busy||!!attempt" @click="clearSelection">{{b('clear')}}</button><button class="primary" :disabled="!fresh||loading||busy||!!attempt||!selectedCount" @click="previewBatch">{{b('preview')}}</button></div><section v-if="data?.employees?.length&&!personFilter" class="wf-section"><h3>{{english()?'Employee hours overview':'员工工时汇总'}}</h3><p class="wf-hint">{{english()?'Whole date range before pagination. Scheduled span includes breaks; actual hours are net. Unknown approvals are not zero. Open a person for daily records.':'汇总所选日期全范围，不仅当前页。排班跨度含休息，实际为净工时；未核准不代表零。点击员工查看每日记录。'}}</p><div class="wf-table-wrap"><table><thead><tr><th>{{p('employee')}}</th><th>{{english()?'Scheduled span / actual net':'排班跨度 / 实际净工时'}}</th><th>{{english()?'Approved / difference from actual':'有效核准 / 与实际差额'}}</th><th>{{b('pending')}}</th></tr></thead><tbody><tr v-for="person in data.employees" :key="person.employeeId"><td><button :disabled="busy||!!attempt" @click="openPerson(person.employeeId)">{{person.employeeName}}</button><br><small>{{person.employeeNo}}</small></td><td>{{hours(person.scheduledSeconds)}} / {{person.actualSeconds==null?'—':hours(person.actualSeconds)}}</td><td>{{person.approvedSeconds==null?'—':hours(person.approvedSeconds)}} / {{person.approvedSeconds==null||person.actualSeconds==null?'—':hours(person.approvedSeconds-person.actualSeconds)}}</td><td>{{person.pending}} / {{person.records}}</td></tr></tbody></table></div></section><button v-if="personFilter" :disabled="busy||!!attempt" @click="backToPeople">{{english()?'Back to employee overview':'返回员工汇总'}}</button><div v-if="data&&(personFilter||!data.employees?.length)" class="wf-table-wrap"><table><thead><tr><th v-if="home?.employeeManage"><input type="checkbox" :aria-label="b('pageAll')" :checked="pageChecked" :disabled="!fresh||loading||busy||!!attempt||!pageEligible.length" @change="pageSelect(($event.target as HTMLInputElement).checked)"></th><th>{{p('workDate')}}</th><th>{{p('employee')}}</th><th>{{b('planned')}} / {{b('actual')}}</th><th>{{b('work')}} / {{b('paid')}} / {{b('unpaid')}}</th><th>{{p('status')}}</th><th></th></tr></thead><tbody><template v-for="entry in data.items" :key="entry.row.schedule.id"><tr><td v-if="home?.employeeManage"><input type="checkbox" :aria-label="entry.row.schedule.employeeNo+' '+entry.row.schedule.workDate" :checked="selected(entry.row.schedule.id)" :disabled="!fresh||loading||busy||!!attempt||!batchEligible(entry)" @change="toggle(entry.row.schedule.id,($event.target as HTMLInputElement).checked)"></td><td>{{entry.row.schedule.workDate}}<br><small>{{entry.row.schedule.shift.name}}</small></td><td>{{entry.row.schedule.employeeName}}<br><small>{{entry.row.schedule.employeeNo}}</small><div v-if="entry.managerEmployee" class="wf-badge">{{b('adminOnly')}}</div></td><td><small>{{stamp(entry.row.schedule.startAt)}} → {{stamp(entry.row.schedule.endAt)}}</small><br>{{stamp(entry.inAt)}} → {{stamp(entry.outAt)}}</td><td>{{hours(entry.row.workSeconds)}} / {{hours(entry.row.paidLeaveSeconds)}} / {{hours(entry.row.unpaidLeaveSeconds)}}</td><td class="wf-wrap-text"><span class="wf-badge">{{entry.row.exempt?w('exempt'):b(entry.category)}}</span><div v-for="finding in entry.row.findings||[]" :key="finding.code">{{finding.name}}</div><div v-for="code in entry.row.issues" :key="code" class="wf-issue">{{issue(code)}}</div><small v-if="!entry.canReview">{{reviewBoardError(entry.reviewBlock,english())}}</small></td><td><button :disabled="!fresh||busy||!!attempt" @click="expanded=expanded===entry.row.schedule.id?'':entry.row.schedule.id">{{b(expanded===entry.row.schedule.id?'collapse':'review')}}</button></td></tr><tr v-if="expanded===entry.row.schedule.id"><td :colspan="home?.employeeManage?7:6"><ApprovalDetail :key="entry.row.schedule.id" :schedule-id="entry.row.schedule.id" inline @saved="saved"/></td></tr></template><tr v-if="!data.items.length"><td colspan="7" class="wf-empty">{{b('noData')}}</td></tr></tbody></table></div><div v-if="data" class="wf-form-actions"><span>{{data.total?offset+1:0}}–{{Math.min(offset+50,data.total)}} / {{data.total}}</span><button :disabled="busy||!!attempt||loading||offset===0" @click="move(-50)">{{b('previous')}}</button><button :disabled="busy||!!attempt||loading||offset+50>=data.total" @click="move(50)">{{b('next')}}</button></div><details v-if="data?.days.length" class="wf-section"><summary>{{b('dayProgress')}}</summary><div class="wf-table-wrap"><table><thead><tr><th>{{p('workDate')}}</th><th>{{b('total')}}</th><th>{{b('current')}}</th><th>{{b('pending')}}</th></tr></thead><tbody><tr v-for="day in data.days" :key="day.date"><td>{{day.date}}</td><td>{{day.total}}</td><td>{{day.current}}</td><td>{{day.total-day.current}}</td></tr></tbody></table></div></details><section v-if="outcomes.length" class="wf-section"><strong>{{b('succeeded')}} {{outcomes.filter(r=>r.success).length}} · {{b('failed')}} {{outcomes.filter(r=>!r.success).length}}</strong><p v-for="row in outcomes.filter(r=>!r.success)" :key="row.scheduleId" class="wf-issue">{{person(row.scheduleId)}} · {{reviewBoardError(row.code,english())}}</p></section><ApprovalBatchPreview v-if="preview" :data="preview" :disabled="busy||!!attempt" :english="english()" :failure="batchFailure" :processed="attempt?.offset||0" :retry="!!attempt&&!busy" @close="preview=null" @confirm="start" @recover="send"/></section></template>
<style scoped>.wf-review-tabs{display:flex;gap:6px;flex-wrap:wrap}.wf-review-tabs button{padding:6px 10px}.wf-table-wrap td{vertical-align:top}.wf-table-wrap small{line-height:1.5}</style>

